const text = $input.item.json.text || "";

function sanitize(input) {
  return input
    .replace(/\*\*/g, "")
    .replace(/#{1,6}\s?/g, "")
    .replace(/~~.*?~~/g, "")
    .replace(/_([^_]+)_/g, "$1")
    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
    .replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}]/gu, "")
    .replace(/\n\s*\n/g, "\n\n")
    .trim();
}

const clean_text = sanitize(text);

if (!clean_text || clean_text.length < 10) {
  throw new Error("Input text is empty or too short for TTS generation");
}

return { json: { clean_text } };

const items = $input.all();
const fullText = items[0].json.clean_text;
const MAX_CHARS = 1200;
const chunks = [];
let remainingText = fullText;

while (remainingText.length > 0) {
  if (remainingText.length <= MAX_CHARS) {
    chunks.push(remainingText);
    break;
  }
  const slice = remainingText.substring(0, MAX_CHARS);

  // Priority 1: split at paragraph break
  let splitIdx = slice.lastIndexOf('\n\n');

  // Priority 2: split at sentence boundary
  if (splitIdx === -1 || splitIdx < MAX_CHARS * 0.3) {
    const sentenceIdx = Math.max(
      slice.lastIndexOf('. '),
      slice.lastIndexOf('? '),
      slice.lastIndexOf('! ')
    );
    if (sentenceIdx > splitIdx) splitIdx = sentenceIdx;
  }

  // Priority 3: split at any whitespace
  if (splitIdx === -1) splitIdx = slice.lastIndexOf(' ');
  if (splitIdx === -1) splitIdx = MAX_CHARS;

  const finalSlice = remainingText.substring(0, splitIdx + 1).trim();
  chunks.push(finalSlice);
  remainingText = remainingText.substring(splitIdx + 1).trim();
}

return chunks.map((chunk, index) => ({
  json: { chunk_text: chunk, chunk_index: index, total_chunks: chunks.length }
}));

const { execSync } = require('child_process');
const fs = require('fs');

const items = $input.all();
if (items.length === 0) return [];

items.sort((a, b) => a.json.chunk_index - b.json.chunk_index);

const apiKey = $env.ELEVENLABS_API_KEY;
const voiceId = $env.ELEVENLABS_VOICE_ID;
const workDir = '/home/node/.n8n';
const chunkFiles = [];

// --- Step 1: Call ElevenLabs sequentially for each chunk ---
for (let i = 0; i < items.length; i++) {
  const chunk = items[i].json.chunk_text;
  const idx = items[i].json.chunk_index;
  const chunkPath = `${workDir}/tts_chunk_${String(idx).padStart(4, '0')}.mp3`;

  let lastError;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const response = await this.helpers.httpRequest({
        url: `https://api.elevenlabs.io/v1/text-to-speech/${voiceId}`,
        method: 'POST',
        headers: {
          'xi-api-key': apiKey,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          text: chunk,
          model_id: 'eleven_v3',
          voice_settings: { stability: 0.5, similarity_boost: 0.80, style: 0.0 }
        }),
        encoding: 'arraybuffer',
      });
      fs.writeFileSync(chunkPath, Buffer.from(response));
      chunkFiles.push(chunkPath);
      lastError = null;
      break;
    } catch (err) {
      lastError = err;
      if (attempt < 2) await new Promise(r => setTimeout(r, 5000));
    }
  }
  if (lastError) throw new Error(`Chunk ${idx} failed after 3 retries: ${lastError.message}`);

  if (i < items.length - 1) {
    await new Promise(r => setTimeout(r, 500));
  }
}

// --- Step 2: Create FFmpeg concat list ---
const listPath = `${workDir}/concat_list.txt`;
fs.writeFileSync(listPath, chunkFiles.map(f => `file '${f}'`).join('\n'));

// --- Step 3: Merge with FFmpeg re-encode (seamless audio, correct duration) ---
const outputPath = `${workDir}/output_final.mp3`;
try {
  execSync(`ffmpeg -y -f concat -safe 0 -i ${listPath} -c:a libmp3lame -b:a 192k -ar 44100 ${outputPath}`, { timeout: 120000 });
} catch (e) {
  if (!fs.existsSync(outputPath)) throw new Error(`FFmpeg merge failed: ${e.message}`);
}

// --- Step 4: Read merged file ---
const mergedBuffer = fs.readFileSync(outputPath);

// --- Step 5: Clean up temp files ---
for (const f of chunkFiles) { try { fs.unlinkSync(f); } catch(e) {} }
try { fs.unlinkSync(listPath); } catch(e) {}

return [{
  json: {
    fileName: 'output_final.mp3',
    size_mb: (mergedBuffer.length / (1024 * 1024)).toFixed(2),
    chunks_merged: items.length,
    output_path: outputPath
  },
  binary: {
    data: await this.helpers.prepareBinaryData(mergedBuffer, 'output_final.mp3', 'audio/mpeg')
  }
}];
